const today = new Date();
for (let i = 1; i < 24; i++) {
  const d = new Date(
    today.getFullYear(),
    today.getMonth() + i,
    today.getDate()
  );
  const option = document.createElement("option");
  option.value = d.getTime();
  option.label = rtf.format(i, "month");
  gExpiryPopup.appendChild(option);
}
for (let i = 2; i <= 10; i++) {
  const d = new Date(
    today.getFullYear() + i,
    today.getMonth(),
    today.getDate()
  );
  const option = document.createElement("option");
  option.value = d.getTime();
  option.label = rtf.format(i, "year");
  gExpiryPopup.appendChild(option);
}
